-- ── story 3-3a: batch block and unpromisable stock ───────────────────────
-- Generated by drizzle-kit (the three column statements) and hand-amended
-- around the generated part: the fail-fast guard, the pre-flight, the
-- pairing CHECK and the post-migration probe (drizzle-kit is blind to CHECKs;
-- `bun run db:generate` afterwards reports "No schema changes").
--
-- `batches.status` has admitted `blocked` since 0010, but nothing could SET
-- it (PENDING). 3-3a adds the block / unblock verb (catalog's
-- `BatchBlockCommand`), which records why, when, by whom and what was said:
--   * `blocked_reason text NULL` — one of `BATCH_BLOCK_REASONS`
--     (src/shared/db/schema.ts — the tuple's home; re-exported by
--     src/modules/catalog/batch-block.command.ts), pinned TS ↔ DB by
--     test/batch-block.spec.ts;
--   * `blocked_at timestamptz NULL`, `blocked_by uuid NULL` (no FK — guide §3);
--   * `blocked_note text NULL` — the block's note (required with `other`).
-- `batches_blocked_pairing`: `status = 'blocked'` ⇔ reason, time and blocker
-- are set (the reason in the vocabulary — `IS NOT NULL` before `IN`, guide
-- §3; a note required when the reason is `other`); an active batch carries
-- none of the four (the unblock clears them all).
--
-- And on `stock_adjustment_pendings` (code review): `batch_resolved_by text
-- NULL` — `fefo` | `explicit` (`BATCH_RESOLVED_BY`, schema.ts), how the pend's
-- batch was resolved at request; only with a `batch_id`. Null on every
-- pre-3-3a pend (the approval then keeps its pre-3-3a inference). The table
-- holds only parked adjustments — small by construction — so its CHECK is
-- added VALID (the 0090 reasoning).
--
-- Additive: five nullable columns, no default — metadata-only, no rewrite.
-- No existing row can be blocked (there was no setter); the pre-flight below
-- PROVES it rather than assuming it, listing every offending row at once.
-- The batches CHECK is added NOT VALID (guide §3 — `batches` grows with every lot a
-- tenant ever received, so a VALID add would scan it under ACCESS
-- EXCLUSIVE): it is enforced on every insert and update from this migration
-- on, and the pre-flight is the proof that every existing row satisfies it
-- (each has `status = 'active'` and the three new columns null). VALIDATE
-- CONSTRAINT runs in a later migration (PENDING, deploy).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'batches' AND column_name = 'blocked_reason'
	) THEN
		RAISE EXCEPTION 'migration 0092: batches.blocked_reason already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
-- ── 1. pre-flight: no batch is blocked yet (design review A6) ────────────
-- A `blocked` row cannot satisfy the pairing CHECK (it has no reason, time
-- or blocker). Nothing in the application could write one; a hand-edited
-- database could. Every such row is named in ONE pass, so an operator fixes
-- them all at once (set it back to `active`, then block it through the verb).
DO $$
DECLARE
	offenders text;
BEGIN
	SELECT string_agg(format('tenant %s sku %s batch %s (%s)', "tenant_id", "sku_id", "id", "code"), '; ' ORDER BY "tenant_id", "id")
	  INTO offenders
	  FROM "batches"
	 WHERE "status" = 'blocked';
	IF offenders IS NOT NULL THEN
		RAISE EXCEPTION 'migration 0092: blocked batches without a reason, time or blocker — set each back to active and re-block it through POST …/inventory/batches/{batchId}/block: %', offenders;
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "blocked_reason" text;--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "blocked_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "blocked_by" uuid;--> statement-breakpoint
ALTER TABLE "batches" ADD COLUMN "blocked_note" text;--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ADD COLUMN "batch_resolved_by" text;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only) ────────────────────────
ALTER TABLE "batches" ADD CONSTRAINT "batches_blocked_pairing" CHECK (
	("status" = 'blocked'
		AND "blocked_reason" IS NOT NULL
		AND "blocked_reason" IN ('recall','qc-failed','contamination','client-instruction','expiry-review','other')
		AND "blocked_at" IS NOT NULL
		AND "blocked_by" IS NOT NULL
		AND ("blocked_reason" <> 'other' OR "blocked_note" IS NOT NULL))
	OR ("status" <> 'blocked'
		AND "blocked_reason" IS NULL
		AND "blocked_at" IS NULL
		AND "blocked_by" IS NULL
		AND "blocked_note" IS NULL)
) NOT VALID;--> statement-breakpoint
ALTER TABLE "stock_adjustment_pendings" ADD CONSTRAINT "stock_adjustment_pendings_batch_resolved_by_check" CHECK (
	"batch_resolved_by" IS NULL
	OR ("batch_resolved_by" IN ('fefo','explicit') AND "batch_id" IS NOT NULL)
);--> statement-breakpoint
-- ── the post-migration assertion (the 0087 / 0091 model) ──────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	s uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	b uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: an active batch (the pre-3-3a shape), a blocked
	-- batch under every reason (with and without a note; `other` with one),
	-- and pends with no batch, a legacy batch pend (null), `fefo`, `explicit`.
	BEGIN
		INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by","blocked_note")
		VALUES
			(gen_random_uuid(), t, s, 'P-ACTIVE', 'active', NULL, NULL, NULL, NULL),
			(gen_random_uuid(), t, s, 'P-RECALL', 'blocked', 'recall', now(), u, NULL),
			(gen_random_uuid(), t, s, 'P-QC', 'blocked', 'qc-failed', now(), u, 'lab report 7'),
			(gen_random_uuid(), t, s, 'P-CONT', 'blocked', 'contamination', now(), u, NULL),
			(gen_random_uuid(), t, s, 'P-CLIENT', 'blocked', 'client-instruction', now(), u, NULL),
			(gen_random_uuid(), t, s, 'P-EXPIRY', 'blocked', 'expiry-review', now(), u, NULL),
			(gen_random_uuid(), t, s, 'P-OTHER', 'blocked', 'other', now(), u, 'label misprint');
		INSERT INTO "stock_adjustment_pendings"
			("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","batch_id","batch_resolved_by")
		VALUES
			(gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, NULL, NULL),
			(gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, gen_random_uuid(), NULL),
			(gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, gen_random_uuid(), 'fefo'),
			(gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, gen_random_uuid(), 'explicit');
		RAISE EXCEPTION USING ERRCODE = 'P0092';
	EXCEPTION
		WHEN check_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0092: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0092' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named CHECK.
	FOREACH probe IN ARRAY ARRAY[
		'blocked without a reason', 'blocked with an unknown reason', 'blocked without a time',
		'blocked without a blocker', 'active with a reason', 'active with a time and blocker',
		'other without a note', 'active with a note',
		'unknown resolution', 'resolution without a batch'
	] LOOP
		refused_by := NULL;
		expected := CASE WHEN probe IN ('unknown resolution', 'resolution without a batch')
			THEN 'stock_adjustment_pendings_batch_resolved_by_check' ELSE 'batches_blocked_pairing' END;
		BEGIN
			CASE probe
				WHEN 'blocked without a reason' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-1', 'blocked', NULL, now(), u);
				WHEN 'blocked with an unknown reason' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-2', 'blocked', 'smelly', now(), u);
				WHEN 'blocked without a time' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-3', 'blocked', 'recall', NULL, u);
				WHEN 'blocked without a blocker' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-4', 'blocked', 'recall', now(), NULL);
				WHEN 'other without a note' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by","blocked_note")
					VALUES (gen_random_uuid(), t, s, 'R-7', 'blocked', 'other', now(), u, NULL);
				WHEN 'active with a note' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_note")
					VALUES (gen_random_uuid(), t, s, 'R-8', 'active', 'stale note');
				WHEN 'unknown resolution' THEN
					INSERT INTO "stock_adjustment_pendings"
						("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","batch_id","batch_resolved_by")
					VALUES (gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, gen_random_uuid(), 'guessed');
				WHEN 'resolution without a batch' THEN
					INSERT INTO "stock_adjustment_pendings"
						("id","tenant_id","warehouse_id","bin_id","sku_id","quantity_milli","reason_code","note","occurred_at","requested_by","requested_at","threshold_quantity_at_request","batch_id","batch_resolved_by")
					VALUES (gen_random_uuid(), t, w, b, s, -5000, 'found', 'n', now(), u, now(), 2, NULL, 'fefo');
				WHEN 'active with a reason' THEN
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-5', 'active', 'recall', NULL, NULL);
				ELSE
					INSERT INTO "batches" ("id","tenant_id","sku_id","code","status","blocked_reason","blocked_at","blocked_by")
					VALUES (gen_random_uuid(), t, s, 'R-6', 'active', NULL, now(), u);
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0092: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "batches" WHERE "tenant_id" = t)
		OR EXISTS (SELECT 1 FROM "stock_adjustment_pendings" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0092: a probe row survived.';
	END IF;
END $$;
